27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private Boolean bulkSignupWarning;
70	
71	    /**
72	     * Number of owners belonging to this owner's household (owners sharing the same
73	     * {@code householdId}), including this owner. Derived at request time rather than stored, and
74	     * used to award the {@code GOLD} membership tier to households of three or more members.
75	     */
76	    @Transient
77	    private Integer householdMemberCount;
78	
79	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
80	    private Set<Pet> pets;
81	
82	    public String getAddress() {
83	        return this.address;
84	    }
85	
86	    public void setAddress(String address) {
87	        this.address = address;
88	    }
89	
90	    public String getCity() {
91	        return this.city;
92	    }
93	
94	    public void setCity(String city) {
95	        this.city = city;
96	    }
97	
98	    public String getTelephone() {
99	        return this.telephone;
100	    }
101	
102	    public void setTelephone(String telephone) {
103	        this.telephone = telephone;
104	    }
105	
106	    public String getEmail() {
107	        return this.email;
108	    }
109	
110	    public void setEmail(String email) {
111	        this.email = email;
112	    }
113	
114	    public LocalDate getRegistrationDate() {
115	        return this.registrationDate;
116	    }
117	
118	    public void setRegistrationDate(LocalDate registrationDate) {
119	        this.registrationDate = registrationDate;
120	    }
121	
122	    public String getCustomerCode() {
123	        return this.customerCode;
124	    }
125	
126	    public void setCustomerCode(String customerCode) {
127	        this.customerCode = customerCode;
128	    }
129	
130	    public String getHouseholdId() {
131	        return this.householdId;
132	    }
133	
134	    public void setHouseholdId(String householdId) {
135	        this.householdId = householdId;
136	    }
137	
138	    public Integer getNamesakeCount() {
139	        return this.namesakeCount;
140	    }
141	
142	    public void setNamesakeCount(Integer namesakeCount) {
143	        this.namesakeCount = namesakeCount;
144	    }
145	
146	    public Boolean getBulkSignupWarning() {
147	        return this.bulkSignupWarning;
148	    }
149	
150	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
151	        this.bulkSignupWarning = bulkSignupWarning;
152	    }
153	
154	    public Integer getHouseholdMemberCount() {
155	        return this.householdMemberCount;
156	    }
157	
158	    public void setHouseholdMemberCount(Integer householdMemberCount) {
159	        this.householdMemberCount = householdMemberCount;
160	    }
161	
162	    protected Set<Pet> getPetsInternal() {
163	        if (this.pets == null) {
164	            this.pets = new HashSet<>();
165	        }
166	        return this.pets;
167	    }
168	
169	    protected void setPetsInternal(Set<Pet> pets) {
170	        this.pets = pets;
171	    }
172	
173	    public List<Pet> getPets() {
174	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
175	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
176	        return Collections.unmodifiableList(sortedPets);
177	    }
178	
179	    public void setPets(List<Pet> pets) {
180	        this.pets = new HashSet<>(pets);
181	    }
182	
183	    public void addPet(Pet pet) {
184	        getPetsInternal().add(pet);
185	        pet.setOwner(this);
186	    }
187	
188	    /**
189	     * Return the Pet with the given name, or null if none found for this Owner.
190	     *
191	     * @param name to test
192	     * @return true if pet name is already in use
193	     */
194	    public Pet getPet(String name) {
195	        return getPet(name, false);
196	    }
197	
198	    /**
199	     * Return the Pet with the given name, or null if none found for this Owner.
200	     *
201	     * @param name to test
202	     * @return true if pet name is already in use
203	     */
204	    public Pet getPet(String name, boolean ignoreNew) {
205	        name = name.toLowerCase();
206	        for (Pet pet : getPetsInternal()) {
207	            if (!ignoreNew || !pet.isNew()) {
208	                String compName = pet.getName();
209	                compName = compName.toLowerCase();
210	                if (compName.equals(name)) {
211	                    return pet;
212	                }
213	            }
214	        }
215	        return null;
216	    }
217	
218	    public Pet getPet(Integer petId) {
219	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
220	    }
221	
222	    @Override
223	    public String toString() {
224	        return new ToStringCreator(this)
225	
226	            .append("id", this.getId())
227	            .append("new", this.isNew())
228	            .append("lastName", this.getLastName())
229	            .append("firstName", this.getFirstName())
230	            .append("address", this.address)
231	            .append("city", this.city)
232	            .append("telephone", this.telephone)
233	            .toString();
234	    }
235	}
