17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
31	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
40	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
50	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
51	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
74	    private static final int MAX_OWNERS_PER_CITY = 50;
75	
76	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
77	    private static final int MAX_OWNERS_PER_DAY = 100;
78	
79	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
80	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    private final TelephoneNormalizer telephoneNormalizer;
91	
92	    private final AddressNormalizer addressNormalizer;
93	
94	    private final EmailNormalizer emailNormalizer;
95	
96	    private final IdentityKeyResolver identityKeyResolver;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 TelephoneNormalizer telephoneNormalizer,
103	                                 AddressNormalizer addressNormalizer,
104	                                 EmailNormalizer emailNormalizer,
105	                                 IdentityKeyResolver identityKeyResolver) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	        this.telephoneNormalizer = telephoneNormalizer;
111	        this.addressNormalizer = addressNormalizer;
112	        this.emailNormalizer = emailNormalizer;
113	        this.identityKeyResolver = identityKeyResolver;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        owners.forEach(this::populateHouseholdMemberCount);
129	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
130	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        populateHouseholdMemberCount(owner);
141	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
142	    }
143	
144	    /**
145	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
146	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
147	     * by the mapper alone.
148	     *
149	     * @param owner the owner to map
150	     * @return the owner DTO carrying its identity key
151	     */
152	    private OwnerDto toOwnerDto(Owner owner) {
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
155	        return ownerDto;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
162	        normalizeAndValidate(ownerFieldsDto);
163	        HttpHeaders headers = new HttpHeaders();
164	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
165	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
166	        owner.setNamesakeCount(countNamesakes(owner));
167	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
168	        assignHouseholdId(owner, ownerFieldsDto);
169	        requireUniqueIdentity(owner);
170	        this.clinicService.saveOwner(owner);
171	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
174	        populateHouseholdMemberCount(owner);
175	        OwnerDto ownerDto = toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    /**
182	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
183	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
184	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
185	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
186	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
187	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
188	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
189	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
190	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
191	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
192	     * assigned (see {@link #requireUniqueIdentity}).
193	     *
194	     * @param ownerFieldsDto the incoming owner payload, mutated in place
195	     * @throws MissingOwnerFieldsException if any required field is missing or blank
196	     */
197	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
198	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
199	        validateRequiredFields(ownerFieldsDto);
200	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
201	        ownerFieldsDto.setTelephone(telephone);
202	        requireCityHasCapacity(ownerFieldsDto.getCity());
203	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
204	        ownerFieldsDto.setRegistrationDate(registrationDate);
205	        requireDailyLimitNotReached(registrationDate);
206	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
207	        ownerFieldsDto.setEmail(email);
208	    }
209	
210	    /**
211	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
212	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
213	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
214	     *
215	     * @param ownerFieldsDto the incoming owner payload
216	     * @return the effective registration date rolled forward onto a business day
217	     */
218	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
219	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
220	        if (effective == null) {
221	            effective = LocalDate.now();
222	        }
223	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
224	            effective = effective.plusDays(1);
225	        }
226	        return effective;
227	    }
228	
229	    /**
230	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
231	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
232	     * further owner may be created for that day.
233	     *
234	     * @param registrationDate the adjusted business-day registration date of the owner being created
235	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
236	     */
237	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
238	        long createdThatDay = this.clinicService.findAllOwners().stream()
239	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
240	            .count();
241	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
242	            throw new DailyOwnerLimitExceededException(
243	                "the maximum number of owners for today has already been reached");
244	        }
245	    }
246	
247	    /**
248	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
249	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
250	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
251	     * reflects only owners that predate it.
252	     *
253	     * @param registrationDate the adjusted business-day registration date of the owner being created
254	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
255	     */
256	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
257	        long createdThatDay = this.clinicService.findAllOwners().stream()
258	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
259	            .count();
260	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
261	    }
262	
263	    /**
264	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
265	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
266	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
267	     * city (e.g. {@code LON-SMI-0007}).
268	     *
269	     * @param city     the owner's city
270	     * @param lastName the owner's last name
271	     * @return the generated customer code
272	     */
273	    private String generateCustomerCode(String city, String lastName) {
274	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
275	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
276	        int sequence = (int) this.clinicService.findAllOwners().stream()
277	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
278	            .count() + 1;
279	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
280	    }
281	
282	    /**
283	     * Counts how many existing owners already share the given owner's first and last name, compared
284	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
285	     * create; it is zero when the owner's name is unique.
286	     *
287	     * @param owner the newly mapped owner about to be saved
288	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
289	     */
290	    private int countNamesakes(Owner owner) {
291	        String firstName = owner.getFirstName();
292	        String lastName = owner.getLastName();
293	        return (int) this.clinicService.findAllOwners().stream()
294	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
295	                && lastName.equalsIgnoreCase(existing.getLastName()))
296	            .count();
297	    }
298	
299	    /**
300	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
301	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
302	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
303	     *
304	     * @param ownerFieldsDto the owner payload to validate
305	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
306	     */
307	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
308	        List<String> missingFields = new ArrayList<>();
309	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
310	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
311	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
312	        requireText(missingFields, "city", ownerFieldsDto.getCity());
313	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
314	        if (!missingFields.isEmpty()) {
315	            throw new MissingOwnerFieldsException(missingFields);
316	        }
317	    }
318	
319	    private void requireText(List<String> missingFields, String fieldName, String value) {
320	        if (value == null || value.isBlank()) {
321	            missingFields.add(fieldName);
322	        }
323	    }
324	
325	    /**
326	     * Rejects creating an owner whose whole derived {@code identityKey} (see
327	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
328	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
329	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
330	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
331	     *
332	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
333	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
334	     */
335	    private void requireUniqueIdentity(Owner owner) {
336	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
337	        boolean inUse = this.clinicService.findAllOwners().stream()
338	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
339	        if (inUse) {
340	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
341	        }
342	    }
343	
344	    /**
345	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
346	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
347	     *
348	     * @param city the city of the owner being created
349	     * @throws OwnerCityFullException if the city already contains 50 or more owners
350	     */
351	    private void requireCityHasCapacity(String city) {
352	        long cityOwners = this.clinicService.findAllOwners().stream()
353	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
354	            .count();
355	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
356	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
357	        }
358	    }
359	
360	    /**
361	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
362	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
363	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
364	     * incidental formatting differences and abbreviation variants do not affect membership.
365	     *
366	     * @param ownerFieldsDto the incoming owner payload
367	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
368	     *         them; empty when none match
369	     */
370	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
371	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
372	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
373	        return this.clinicService.findAllOwners().stream()
374	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
375	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
376	            .toList();
377	    }
378	
379	    /**
380	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
381	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
382	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
383	     * identifier is derived deterministically from the household's last name and address (see
384	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
385	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
386	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
387	     *
388	     * @param owner          the newly mapped owner about to be saved
389	     * @param ownerFieldsDto the incoming owner payload
390	     */
391	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
392	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
393	            return;
394	        }
395	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
396	        if (members.isEmpty()) {
397	            return;
398	        }
399	        String householdId =
400	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
401	        owner.setHouseholdId(householdId);
402	        backfillHouseholdMembers(householdId, members);
403	    }
404	
405	    /**
406	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
407	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
408	     * into line so the whole household shares the single value; members that already carry it are left untouched.
409	     *
410	     * @param householdId the shared household identifier
411	     * @param members     the existing owners in the household
412	     */
413	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
414	        for (Owner member : members) {
415	            if (!householdId.equals(member.getHouseholdId())) {
416	                member.setHouseholdId(householdId);
417	                this.clinicService.saveOwner(member);
418	            }
419	        }
420	    }
421	
422	    /**
423	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
424	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
425	     * household is counted as a household of one.
426	     *
427	     * @param owner the owner whose household size should be resolved
428	     */
429	    private void populateHouseholdMemberCount(Owner owner) {
430	        String householdId = owner.getHouseholdId();
431	        if (householdId == null) {
432	            owner.setHouseholdMemberCount(1);
433	            return;
434	        }
435	        long members = this.clinicService.findAllOwners().stream()
436	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
437	            .count();
438	        owner.setHouseholdMemberCount((int) members);
439	    }
440	
441	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
442	    @Override
443	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
444	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
445	        if (currentOwner == null) {
446	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
447	        }
448	        currentOwner.setAddress(ownerFieldsDto.getAddress());
449	        currentOwner.setCity(ownerFieldsDto.getCity());
450	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
451	        currentOwner.setLastName(ownerFieldsDto.getLastName());
452	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
453	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
454	        this.clinicService.saveOwner(currentOwner);
455	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
456	    }
457	
458	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
459	    @Transactional
460	    @Override
461	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
462	        Owner owner = this.clinicService.findOwnerById(ownerId);
463	        if (owner == null) {
464	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
465	        }
466	        this.clinicService.deleteOwner(owner);
467	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
468	    }
469	
470	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
471	    @Override
472	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
473	        Owner owner = this.clinicService.findOwnerById(ownerId);
474	        if (owner == null) {
475	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
476	        }
477	        HttpHeaders headers = new HttpHeaders();
478	        Pet pet = petMapper.toPet(petFieldsDto);
479	        owner.setId(ownerId);
480	        pet.setOwner(owner);
481	        pet.getType().setName(null);
482	        this.clinicService.savePet(pet);
483	        PetDto petDto = petMapper.toPetDto(pet);
484	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
485	            .buildAndExpand(pet.getId()).toUri());
486	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
487	    }
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Override
491	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
492	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
493	        if (currentOwner != null) {
494	            Pet currentPet = this.clinicService.findPetById(petId);
495	            if (currentPet != null) {
496	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
497	                currentPet.setName(petFieldsDto.getName());
498	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
499	                this.clinicService.savePet(currentPet);
500	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
501	            }
502	        }
503	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
504	    }
505	
506	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
507	    @Override
508	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
509	        HttpHeaders headers = new HttpHeaders();
510	        Visit visit = visitMapper.toVisit(visitFieldsDto);
511	        Pet pet = new Pet();
512	        pet.setId(petId);
513	        visit.setPet(pet);
514	        this.clinicService.saveVisit(visit);
515	        VisitDto visitDto = visitMapper.toVisitDto(visit);
516	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
517	            .buildAndExpand(visit.getId()).toUri());
518	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
519	    }
520	
521	
522	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
523	    @Override
524	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
525	        Owner owner = this.clinicService.findOwnerById(ownerId);
526	        if (owner != null) {
527	            Pet pet = owner.getPet(petId);
528	            if (pet != null) {
529	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
530	            }
531	        }
532	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
533	    }
534	}
