17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.LinkedHashMap;
20	import java.util.Map;
21	
22	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Turns owner telephone numbers into the single canonical E.164 form that gets stored, returned and compared, so the
27	 * REST controllers do not have to carry the telephone rules themselves.
28	 *
29	 * <p>Canonicalization keeps a leading {@code '+'} and country code when one is supplied; otherwise it assumes the
30	 * default country code {@code +61} and drops a single leading {@code '0'} from the national digits. Spaces, dashes and
31	 * brackets (indeed every non-digit character other than the leading {@code '+'}) are stripped. So {@code "0412 345 678"}
32	 * becomes {@code "+61412345678"}.
33	 *
34	 * <p>Two entry points share one notion of "canonical": {@link #normalize(String)} validates a raw value supplied on a
35	 * request and rejects anything that cannot form a valid E.164 number, while {@link #canonicalize(String)} reduces an
36	 * already-stored value to the same form for duplicate detection without rejecting it.
37	 */
38	@Component
39	public class TelephoneNormalizer {
40	
41	    /** Country code assumed for national-format numbers that do not carry an explicit {@code '+'} prefix. */
42	    private static final String DEFAULT_COUNTRY_CODE = "61";
43	
44	    /** Minimum number of digits an E.164 number may carry after the leading {@code '+'}. */
45	    private static final int MIN_E164_DIGITS = 8;
46	
47	    /** Maximum number of digits an E.164 number may carry after the leading {@code '+'}. */
48	    private static final int MAX_E164_DIGITS = 15;
49	
50	    /**
51	     * Exact number of national digits (digits following the country code) required for each known country code.
52	     * Ordered longest country code first so the most specific prefix wins when one code is a prefix of another.
53	     */
54	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = buildNationalDigitsByCountryCode();
55	
56	    private static Map<String, Integer> buildNationalDigitsByCountryCode() {
57	        Map<String, Integer> byLongestFirst = new LinkedHashMap<>();
58	        byLongestFirst.put("61", 9);
59	        byLongestFirst.put("1", 10);
60	        return byLongestFirst;
61	    }
62	
63	    /**
64	     * Normalizes a raw request telephone into its canonical stored E.164 form. A leading {@code '+'} and country code
65	     * are kept when present; otherwise the default country code {@code +61} is assumed and a single leading {@code '0'}
66	     * is dropped from the national digits. Spaces, dashes and brackets are stripped. The result must carry 8 to 15
67	     * digits after the {@code '+'}. The normalized E.164 value is what gets stored and returned as {@code telephone}.
68	     *
69	     * @param telephone the raw telephone value from the request
70	     * @return the normalized canonical E.164 telephone
71	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
72	     */
73	    public String normalize(String telephone) {
74	        String e164 = toE164(telephone);
75	        int digitCount = e164.length() - 1;
76	        if (digitCount < MIN_E164_DIGITS || digitCount > MAX_E164_DIGITS) {
77	            throw new InvalidTelephoneException(
78	                "telephone must contain between " + MIN_E164_DIGITS + " and " + MAX_E164_DIGITS
79	                    + " digits after conversion to E.164 form");
80	        }
81	        validateNationalNumberLength(e164);
82	        return e164;
83	    }
84	
85	    /**
86	     * Rejects a normalized E.164 number whose national number (the digits following the country code) does not carry
87	     * the exact length that country requires. For example {@code +61} numbers must have 9 national digits and
88	     * {@code +1} numbers must have 10. Country codes with no known rule are left to the generic 8-to-15 digit bounds.
89	     *
90	     * @param e164 a normalized E.164 telephone that has already passed the generic digit-count bounds
91	     * @throws InvalidTelephoneException if the national number length is wrong for the recognized country code
92	     */
93	    private void validateNationalNumberLength(String e164) {
94	        String digits = e164.substring(1);
95	        for (Map.Entry<String, Integer> rule : NATIONAL_DIGITS_BY_COUNTRY_CODE.entrySet()) {
96	            String countryCode = rule.getKey();
97	            if (digits.startsWith(countryCode)) {
98	                int nationalDigits = digits.length() - countryCode.length();
99	                int requiredDigits = rule.getValue();
100	                if (nationalDigits != requiredDigits) {
101	                    throw new InvalidTelephoneException(
102	                        "telephone with country code +" + countryCode + " must contain exactly " + requiredDigits
103	                            + " national digits, but had " + nationalDigits);
104	                }
105	                return;
106	            }
107	        }
108	    }
109	
110	    /**
111	     * Reduces an already-stored telephone to the canonical E.164 form used for duplicate detection. Unlike
112	     * {@link #normalize(String)} this never rejects its input, so existing owners are compared regardless of how their
113	     * number was originally formatted.
114	     *
115	     * @param telephone an owner's stored telephone, may be {@code null}
116	     * @return the canonical E.164 form used for comparison
117	     */
118	    public String canonicalize(String telephone) {
119	        return toE164(telephone);
120	    }
121	
122	    /**
123	     * Converts a raw telephone into E.164 form without enforcing the digit-count bounds. When the value carries a
124	     * leading {@code '+'} its country code is kept; otherwise the default country code is prepended after dropping a
125	     * single leading {@code '0'} from the national digits.
126	     */
127	    private String toE164(String telephone) {
128	        if (telephone == null) {
129	            return "+";
130	        }
131	        boolean explicitCountryCode = telephone.trim().startsWith("+");
132	        String digits = digitsOf(telephone);
133	        if (explicitCountryCode) {
134	            return "+" + digits;
135	        }
136	        if (digits.startsWith("0")) {
137	            digits = digits.substring(1);
138	        }
139	        return "+" + DEFAULT_COUNTRY_CODE + digits;
140	    }
141	
142	    private String digitsOf(String telephone) {
143	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
144	    }
145	}
