21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Turns owner addresses into the single canonical form that gets stored, returned and compared, so the REST
25	 * controllers do not have to carry the address rules themselves.
26	 *
27	 * <p>Normalization trims the value and collapses every run of whitespace to a single space, upper-cases it, and expands
28	 * a small set of common abbreviations that appear as whole words: {@code ST -> STREET}, {@code RD -> ROAD} and
29	 * {@code AVE -> AVENUE}. So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and {@code "7 elm ave"} becomes
30	 * {@code "7 ELM AVENUE"}.
31	 *
32	 * <p>The same canonical form is used both for the value that is stored and returned and for every address comparison
33	 * (household duplicate detection and the shared household id), so incidental formatting differences never affect the
34	 * outcome.
35	 */
36	@Component
37	public class AddressNormalizer {
38	
39	    /** Whole-word abbreviations expanded during normalization, keyed by their upper-cased form. */
40	    private static final Map<String, String> ABBREVIATIONS = Map.of(
41	        "ST", "STREET",
42	        "RD", "ROAD",
43	        "AVE", "AVENUE");
44	
45	    /**
46	     * Normalizes an owner address into its canonical stored form: trimmed, whitespace-collapsed, upper-cased and with
47	     * common abbreviations expanded. A {@code null} input yields an empty string, so callers can uniformly treat a
48	     * blank result as a missing address.
49	     *
50	     * @param address the raw address value from the request, may be {@code null}
51	     * @return the normalized canonical address, never {@code null}
52	     */
53	    public String normalize(String address) {
54	        if (address == null) {
55	            return "";
56	        }
57	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase();
58	        if (collapsed.isEmpty()) {
59	            return "";
60	        }
61	        StringBuilder result = new StringBuilder(collapsed.length());
62	        for (String token : collapsed.split(" ")) {
63	            if (result.length() > 0) {
64	                result.append(' ');
65	            }
66	            result.append(ABBREVIATIONS.getOrDefault(token, token));
67	        }
68	        return result.toString();
69	    }
70	}
